(()=>{const BUILD='F2-20260830-1957';document.documentElement.dataset.visionBuild=BUILD;const apply=()=>{const lab=document.querySelector('[data-vision-lab]');if(!lab)return false;let badge=lab.querySelector('[data-vision-build]');if(!badge){badge=document.createElement('div');badge.dataset.visionBuild='';badge.textContent=`BUILD ${BUILD}`;badge.style.cssText='position:absolute;right:10px;bottom:10px;z-index:30;padding:6px 8px;border-radius:999px;background:#111;color:#7dffbd;border:1px solid rgba(125,255,189,.55);font:700 10px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.06em;pointer-events:none;box-shadow:0 0 16px rgba(50,255,160,.18)';lab.querySelector('.vision-stage-v11')?.append(badge);}return true};if(!apply()){const mo=new MutationObserver(()=>{if(apply())mo.disconnect()});mo.observe(document.documentElement,{childList:true,subtree:true});setTimeout(()=>mo.disconnect(),10000)}})();